        rule: '- Zonal Topraklar: Terra-Rossa (Akdeniz kalker üzerinde, kireçli, demir oksitli kırmızı renkli), Kahverengi Orman (Karadeniz, humusça zengin), Çernezyom (Erzurum-Kars, en verimli zonal toprak, kara toprak), Podzol (Batı Karadeniz soğuk nemli çam ormanı altı).\n- Azonal Topraklar (Taşınmış, horizonsuz, verimli): Alüvyal (Akarsu), Kolüvyal (Etek), Moren (Buzul), Lös (Rüzgar), Regosol (Volkanik kum).\n- Bitki Örtüsü: Maki (Kızılçam tahribiyle: Zeytin, defne, zakkum, mersin), Garig (Maki tahribi: Lavanta, abdestbozan), Psödömaki (Karadeniz orman tahribi), Bozkır (Geven, gelincik, çoban yastığı).',
