        rule: '- Tarımda Verim: En büyük sorun SULAMADIR. GAP ile Şanlıurfa pamuk üretiminde 1. sıraya yükselmiştir.\n- Ürünler:\n  * Buğday-Arpa: İlkbaharda yağış, yazın kuraklık ister. Karadeniz kıyılarında yetişmez.\n  * Zeytin, İncir, Turunçgil: Don olayına karşı son derece hassastır.\n  * Çay: Yıkanmış asitli toprak, bol nem ister (Sadece Doğu Karadeniz - Rize).\n  * Fındık: Karadeniz iklimi (Ordu, Giresun dünyada 1.).\n  * Pamuk: Yüksek sıcaklık ve bol su ister (Şanlıurfa, Ege, Çukurova).\n  * Devlet Kontrolündeki Ürünler: Tütün (Kalite), Pirinç (Sıtma hastalığı riski), Haşhaş ve Kenevir (Uyuşturucu kontrolü), Şekerpancarı (Kota ve çabuk bozulma riski).',
