        rule: '- Madenler:\n  * Demir: Sivas (Divriği), Malatya (Hekimhan-Hasançelebi).\n  * Bakır: Artvin (Murgul), Kastamonu (Küre), Elazığ (Maden).\n  * Boksit (Alüminyum): Konya (Seydişehir), Antalya (Akseki).\n  * Krom: Elazığ (Guleman), Muğla (Fethiye).\n  * Bor: Balıkesir (Bigadiç, Susurluk), Kütahya (Emet), Eskişehir (Kırka), Bursa (Mustafakemalpaşa) - Dünyada 1. sıradayız.\n  * Mermer: Afyonkarahisar, Marmara Adası, Bursa, Muğla (İhracatta 1. madenimiz).\n- Enerji:\n  * Taş Kömürü: Zonguldak (Çatalağzı termik santrali - 1. Jeolojik zaman).\n  * Linyit: Manisa (Soma), Kütahya (Tunçbilek), Muğla (Yatağan), K.Maraş (Afşin-Elbistan) - 3. Jeolojik zaman.\n  * Jeotermal: Denizli (Sarayköy), Aydın (Germencik) - Fay hatları.\n  * Rüzgar: İzmir, Balıkesir, Çanakkale.',
