        rule: '- GAP (Güneydoğu Anadolu): Amaç sulama ve hidroelektrik enerji üretimi. Fırat ve Dicle nehirleri üzerinde barajlar (Atatürk Barajı, Ilısu/Veysel Eroğlu). Sanayi bitkileri (pamuk, mısır) patlama yapmıştır.\n- KOP (Konya Ovası Projesi): Mavi Tünel ile Göksu Nehri\'nin suları Konya kapalı havzasına aktarılmıştır. Yeraltı suyunun çekilmesini ve obruk oluşumunu azaltmayı hedefler.\n- DOKAP (Doğu Karadeniz): Yeşil Yol projesi ile yaylaları birbirine bağlamak, yayla turizmi ve balıkçılığı geliştirmek.\n- DAP (Doğu Anadolu): Büyükbaş hayvancılığı geliştirmek, mera ıslahı ve kış turizmi.\n- ZBK (Zonguldak-Bartın-Karabük): Taş kömürü ve demir-çelik üretimini modernleştirmek, Filyos Vadi Projesi ile liman ve sanayi üssü kurmak.',
        examTip: 'GAP sadece bir tarım projesi değil, eğitim, sağlık, altyapı ve ulaştırmayı kapsayan entegre bir BÖLGESEL KALKINMA projesidir!',
